unsigned mismatch(const std::vector<uint32_t>& a,const std::vector<float>& b){if(a.size()!=b.size())throw std::runtime_error("size");unsigned n=0;for(unsigned i=0;i<a.size();++i)n+=a[i]!=word(b[i]);return n;}
std::vector<float> split(const std::vector<float>& a,unsigned h){std::vector<float> b;for(unsigned r=0;r<32;++r)for(unsigned c=0;c<32;++c)b.push_back(a[r*64+h*32+c]);return b;}
// Independent reference, never calls the DSP dot body.
std::vector<double> nt(const std::vector<float>& a,const std::vector<float>& b,bool fp){std::vector<double> v(1024);for(unsigned r=0;r<32;++r)for(unsigned j=0;j<32;++j){double s=0;float f=0;for(unsigned q=0;q<32;++q){if(fp){float p=a[r*32+q]*b[j*32+q];f=f+p;}else s+=double(a[r*32+q])*double(b[j*32+q]);}v[r*32+j]=fp?double(f):s;}return v;}
std::vector<float> floats(const std::vector<double>& v){std::vector<float> a;for(double x:v)a.push_back(float(x));return a;}
double pct(std::vector<double> v,double p){std::sort(v.begin(),v.end());return v[size_t(p*(v.size()-1))];}
struct Graph {
 DiagnosticGraph g;bool mixed,observe,tap;unsigned stage,x,ga,be,dy,y,h,iv,dx,dg,db,lr=~0u,br=~0u,qr=~0u,hr=~0u,rr=~0u;std::array<unsigned,3>w,q;std::array<unsigned,6>heads;std::array<unsigned,2>scores;double finalizeUs=0,firstUs=0;
 Graph(bool m,bool o,bool t,unsigned s):g(std::string(m?"mixed":"hvx")+std::to_string(s)+(o?"Obs":"Free")+(t?"Tap":"Native")),mixed(m),observe(o),tap(t),stage(s){g.receiptEnabled=o;auto native=t?QNN_TENSOR_TYPE_APP_READ:QNN_TENSOR_TYPE_NATIVE;
 x=g.tensor("x",QNN_TENSOR_TYPE_APP_WRITE,{1,1,32,64});y=x;
 if(stage){ga=g.tensor("ga",QNN_TENSOR_TYPE_APP_WRITE,{1,1,1,64});be=g.tensor("be",QNN_TENSOR_TYPE_APP_WRITE,{1,1,1,64});dy=g.tensor("dy",QNN_TENSOR_TYPE_APP_WRITE,{1,1,32,64});y=g.tensor("y",native,{1,1,32,64});h=g.tensor("h",native,{1,1,32,64});iv=g.tensor("iv",native,{1,1,32,1});auto eps=g.constant("eps",{1,1,1,1},{1e-5f});lr=g.tensor("lr",QNN_TENSOR_TYPE_APP_READ,{1,1,1,6313},QNN_DATATYPE_INT_32);std::vector<unsigned> outs={y,h,iv};if(o)outs.push_back(lr);g.node("ln1",o?"S2":"S2NoReceipt","HexaSelectiveLn1",{x,ga,be,eps},outs);
 dx=g.tensor("dx",QNN_TENSOR_TYPE_APP_READ,{1,1,32,64});dg=g.tensor("dg",QNN_TENSOR_TYPE_APP_READ,{1,1,1,64});db=g.tensor("db",QNN_TENSOR_TYPE_APP_READ,{1,1,1,64});br=g.tensor("br",QNN_TENSOR_TYPE_APP_READ,{1,1,1,6248},QNN_DATATYPE_INT_32);g.node("backward","LnBackward","HexaFp32",{dy,ga,h,iv},{dx,dg,db,br});}
 for(unsigned p=0;p<3;++p){w[p]=g.tensor(("w"+std::to_string(p)).c_str(),QNN_TENSOR_TYPE_APP_WRITE,{1,1,64,64});q[p]=g.tensor(("q"+std::to_string(p)).c_str(),stage<2?QNN_TENSOR_TYPE_APP_READ:native,{1,1,32,64});}qr=g.tensor("qr",QNN_TENSOR_TYPE_APP_READ,{1,1,1,m?20512u:20504u},QNN_DATATYPE_INT_32);
 if(m){std::vector<unsigned> out={q[0],q[1],q[2]};if(o)out.push_back(qr);g.node("projection",o?"MixedPrecisionQKV":"MixedPrecisionQKVNoReceipt","HexaMixedQkv",{y,w[0],w[1],w[2]},out);}else g.node("projection","ProjectionQKVHvx","HexaFp32",{y,w[0],w[1],w[2]},{q[0],q[1],q[2],qr});
 if(stage>=2){for(unsigned p=0;p<6;++p)heads[p]=g.tensor(("head"+std::to_string(p)).c_str(),stage==2||p>=4?QNN_TENSOR_TYPE_APP_READ:native,{1,1,32,32});hr=g.tensor("hr",QNN_TENSOR_TYPE_APP_READ,{1,1,1,12296},QNN_DATATYPE_INT_32);g.node("heads","QKVHeads","HexaFp32",{q[0],q[1],q[2]},{heads[0],heads[1],heads[2],heads[3],heads[4],heads[5],hr});}
 if(stage==3){for(unsigned p=0;p<2;++p)scores[p]=g.tensor(("score"+std::to_string(p)).c_str(),QNN_TENSOR_TYPE_APP_READ,{1,1,32,32});rr=g.tensor("rr",QNN_TENSOR_TYPE_APP_READ,{1,1,1,6152},QNN_DATATYPE_INT_32);g.node("raw_qk","ForwardQKRaw","HexaFp32",{heads[0],heads[1],heads[2],heads[3]},{scores[0],scores[1],rr});}
 auto start=std::chrono::steady_clock::now();g.finalize();finalizeUs=std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-start).count();
 }
 auto run(const mixedfixture::Case& c,const s2fixture::Case& ln){std::map<unsigned,std::vector<float>> in={{x,stage?ln.x:c.y}};for(unsigned p=0;p<3;++p)in[w[p]]=c.w[p];if(stage){in[ga]=ln.ga;in[be]=ln.be;in[dy]=ln.dy;}auto out=g.run(in);if(!firstUs)firstUs=g.executeUs;return out;}
};
unsigned failures=0,records=0;std::map<std::string,std::vector<uint32_t>> anchors;std::map<std::string,std::vector<uint32_t>> vbaseline;
void numerical(Graph& g,const mixedfixture::Case& c,const std::string& field,const std::vector<uint32_t>& words,const std::vector<float>& expected,const std::vector<double>& ref,double gate,bool requireWords=true){auto e=phonelm::qnn::lnvalidation::errors(ref,decode(words));unsigned n=mismatch(words,expected);bool pass=!e.nonfinite&&e.absolute<=gate&&(!requireWords||!n);std::string key=std::to_string(g.mixed)+":"+std::to_string(g.stage)+":"+std::to_string(c.index)+":"+field;unsigned variant=0;if(g.observe&&g.tap)anchors[key]=words;else variant=anchors.at(key)!=words;pass=pass&&!variant;failures+=!pass;++records;std::printf("{\"kind\":\"numerical\",\"mixed\":%d,\"stage\":%u,\"observed\":%d,\"tap\":%d,\"case\":%u,\"set\":%u,\"field\":\"%s\",\"maxAbs\":%.17g,\"rms\":%.17g,\"word_mismatches\":%u,\"variant_mismatches\":%u,\"hash\":\"%016llx\",\"gate\":%d}\n",g.mixed,g.stage,g.observe,g.tap,c.index,c.set,field.c_str(),e.absolute,e.rms,n,variant,(unsigned long long)hashWords(decode(words)),pass);}
void inspect(Graph& g,const mixedfixture::Case& c,const s2fixture::Case& ln,const std::map<unsigned,std::vector<uint32_t>>& out,unsigned times[4],bool report){
 auto require=[](bool b){if(!b)throw std::runtime_error("receipt integrity");};std::vector<uint32_t> q[3],lh[3],hh[6];for(unsigned p=0;p<3;++p)if(out.count(g.q[p]))q[p]=out.at(g.q[p]);
 if(g.stage){unsigned ids[]={g.y,g.h,g.iv,g.dx,g.dg,g.db};for(unsigned p=0;p<3;++p)if(out.count(ids[p]))lh[p]=out.at(ids[p]);
 if(g.observe){auto& r=out.at(g.lr);require(r.size()==6313&&r[0]==0x48383202&&r[1]&&r[5]==81);unsigned at=8;for(auto* v:{&ln.x,&ln.ga,&ln.be})for(float x:*v)require(r.at(at++)==word(x));require(r.at(at++)==word(1e-5f));for(unsigned p=0;p<3;++p){std::vector<uint32_t> a(r.begin()+at,r.begin()+at+s2fixture::sizes[p]);if(!lh[p].empty())require(lh[p]==a);lh[p]=a;at+=a.size();}require(at==6313);auto& b=out.at(g.br);require(b.size()==6248&&b[0]==0x48383105&&b[1]&&b[5]==81);at=8;for(auto* v:{&ln.dy,&ln.ga})for(float x:*v)require(b.at(at++)==word(x));for(unsigned p:{1u,2u})for(auto x:lh[p])require(b.at(at++)==x);for(auto x:out.at(g.dx))require(b.at(at++)==x);require(at==6248);}
 if(report)for(unsigned p=0;p<6;++p){std::vector<uint32_t> value=p<3?lh[p]:out.at(ids[p]);if(!value.empty())numerical(g,c,"ln"+std::to_string(p),value,ln.expected[1][p],ln.reference[p],p<3?.002:.02);}}
 if(g.observe){auto& r=out.at(g.qr);unsigned hd=g.mixed?32:24;require(r.size()==(g.mixed?20512:20504)&&r[0]==(g.mixed?0x48383301u:0x48383115u)&&r[1]&&r[2]==14336&&r[3]==6144&&r[5]==81&&r[15]==128);if(g.mixed)require(r[26]==1&&r[27]==1);unsigned at=hd;for(unsigned j=0;j<2048;++j)require(r.at(at++)==(g.stage?lh[0][j]:word(c.y[j])));for(auto& w:c.w)for(float x:w)require(r.at(at++)==word(x));for(unsigned p=0;p<3;++p){std::vector<uint32_t> a(r.begin()+at,r.begin()+at+2048);if(!q[p].empty())require(q[p]==a);q[p]=a;at+=2048;}require(at==r.size());times[0]=r[4];times[1]=r[7];times[2]=g.mixed?r[24]:0;times[3]=g.mixed?r[25]:0;}
 if(report)for(unsigned p=0;p<3;++p)if(!q[p].empty()){numerical(g,c,"qkv"+std::to_string(p),q[p],c.expected[g.mixed][p],c.local[p],c.set==2?1e30:.002);if(g.stage)numerical(g,c,"idealLnQkv"+std::to_string(p),q[p],c.expected[g.mixed][p],c.ideal[p],.002);if(p==2){auto key=std::to_string(g.stage)+":"+std::to_string(g.observe)+":"+std::to_string(g.tap)+":"+std::to_string(c.index);if(!g.mixed)vbaseline[key]=q[p];else require(vbaseline.at(key)==q[p]);}}
 if(g.stage>=2){for(unsigned p=0;p<6;++p)if(out.count(g.heads[p]))hh[p]=out.at(g.heads[p]);if(g.observe){auto& r=out.at(g.hr);require(r.size()==12296&&r[0]==0x48383113u&&r[1]&&r[5]==81);unsigned at=8;for(auto& v:q)for(auto x:v)require(r.at(at++)==x);for(unsigned p=0;p<6;++p){std::vector<uint32_t> a(r.begin()+at,r.begin()+at+1024);if(!hh[p].empty())require(hh[p]==a);hh[p]=a;at+=1024;}require(at==12296);for(unsigned p=0;p<6;++p)for(unsigned row=0;row<32;++row)for(unsigned col=0;col<32;++col)require(hh[p][row*32+col]==q[p/2][row*64+(p%2)*32+col]);}
 if(report)for(unsigned p=0;p<6;++p)if(!hh[p].empty()){auto ex=split(c.expected[g.mixed][p/2],p%2);std::vector<double> ref(ex.begin(),ex.end());numerical(g,c,"head"+std::to_string(p),hh[p],ex,ref,0);}}
 if(g.stage==3){if(g.observe){auto& r=out.at(g.rr);require(r.size()==6152&&r[0]==0x48383116u&&r[1]&&r[5]==81);unsigned at=8;for(unsigned p=0;p<4;++p)for(auto x:hh[p])require(r.at(at++)==x);for(unsigned p=0;p<2;++p)for(auto x:out.at(g.scores[p]))require(r.at(at++)==x);require(at==6152);}
 if(report)for(unsigned p=0;p<2;++p){auto a=split(c.expected[g.mixed][0],p),b=split(c.expected[g.mixed][1],p);numerical(g,c,"score"+std::to_string(p),out.at(g.scores[p]),floats(nt(a,b,true)),nt(a,b,false),.01);}}
}
