int main(int argc,char** argv){if(argc!=3)return 1;try{auto cs=mixedfixture::load(argv[1]);auto ls=s2fixture::load(argv[2]);initializeMixed();std::vector<mixedprobe::Graph*> graphs;
 for(unsigned stage=0;stage<4&&!mixedprobe::failures;++stage)for(bool mixed:{false,true})for(bool observe:{true,false})for(bool tap:{true,false}){auto* gp=new mixedprobe::Graph(mixed,observe,tap,stage);graphs.push_back(gp);for(auto& c:cs){if(stage&&c.index>=60)continue;auto out=gp->run(c,ls[std::min(c.index,59u)]);unsigned ts[4]={};mixedprobe::inspect(*gp,c,ls[std::min(c.index,59u)],out,ts,true);std::printf("{\"kind\":\"execution\",\"mixed\":%d,\"stage\":%u,\"observed\":%d,\"tap\":%d,\"case\":%u,\"execute_us\":%.3f,\"arithmetic_us\":%u,\"receipt_us\":%u,\"qk_us\":%u,\"v_us\":%u,\"native_receipts_checked\":%d}\n",mixed,stage,observe,tap,c.index,gp->g.executeUs,ts[0],ts[1],ts[2],ts[3],observe);}}
 if(!mixedprobe::failures)for(auto* gp:graphs){auto& g=*gp;std::vector<double> t[5];for(unsigned i=0;i<32;++i){auto out=g.run(cs[0],ls[0]);unsigned ts[4]={};mixedprobe::inspect(g,cs[0],ls[0],out,ts,false);if(i){t[0].push_back(g.g.executeUs);if(g.observe)for(unsigned k=0;k<4;++k)t[k+1].push_back(ts[k]);}}unsigned native=0,host=0;for(unsigned id=0;id<g.g.tensors.size();++id){auto type=g.g.tensors[id].v1.type;if(type==QNN_TENSOR_TYPE_NATIVE)native+=g.g.size(id)*4;if(type==QNN_TENSOR_TYPE_APP_READ||type==QNN_TENSOR_TYPE_APP_WRITE)host+=g.g.size(id)*4;}
 std::printf("{\"kind\":\"performance\",\"mixed\":%d,\"stage\":%u,\"observed\":%d,\"tap\":%d,\"samples\":31,\"finalize_us\":%.3f,\"first_us\":%.3f,\"median_us\":%.3f,\"p10_us\":%.3f,\"p90_us\":%.3f,\"math_us\":%.3f,\"receipt_us\":%.3f,\"qk_us\":%.3f,\"v_us\":%.3f,\"nodes\":%u,\"tensors\":%zu,\"native_bytes\":%u,\"host_bytes\":%u,\"mixed_explicit_scratch_bytes\":0}\n",g.mixed,g.stage,g.observe,g.tap,g.finalizeUs,g.firstUs,mixedprobe::pct(t[0],.5),mixedprobe::pct(t[0],.1),mixedprobe::pct(t[0],.9),g.observe?mixedprobe::pct(t[1],.5):0,g.observe?mixedprobe::pct(t[2],.5):0,g.observe&&g.mixed?mixedprobe::pct(t[3],.5):0,g.observe&&g.mixed?mixedprobe::pct(t[4],.5):0,g.g.nodes,g.g.tensors.size(),native,host);}
 closeProbe();std::printf("summary,mixed_qkv,required_failures=%u,numerical_records=%u,cases=68,native_cases=60,variants=32,cpu_fallback=0,input_mutation=0,finite=1,poison_remaining=0,canary=1,teardown=1\n",mixedprobe::failures,mixedprobe::records);return mixedprobe::failures?4:0;
 }catch(const std::exception& e){std::fprintf(stderr,"%s\n",e.what());return 4;}}
